import unittest
from pet_talents import RobotPet, RobotCat, RobotBird, RobotDog


class TestRobotPet(unittest.TestCase):
    def setUp(self):
        self.pet = RobotPet("Robo")

    def test_speak_low_battery(self):
        self.pet.battery = 10
        self.assertIn("recharge", self.pet.speak())

    def test_speak_happy(self):
        self.pet.mood = "happy"
        self.pet.battery = 50
        self.assertIn("happy", self.pet.speak())

    def test_speak_neutral(self):
        self.pet.mood = "neutral"
        self.pet.battery = 50
        self.assertIn("Hello", self.pet.speak())

    def test_speak_contains_name(self):
        self.assertIn("Robo", self.pet.speak())


